--
-- Table structure for table `matches`
--

DROP TABLE IF EXISTS `matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category` enum('SMA','SMP') COLLATE utf8mb4_unicode_ci NOT NULL,
  `stage` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `round_label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `round_order` tinyint unsigned NOT NULL DEFAULT '0',
  `slot` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `winner_next_match_id` bigint unsigned DEFAULT NULL,
  `winner_next_side` enum('team1','team2') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loser_next_match_id` bigint unsigned DEFAULT NULL,
  `loser_next_side` enum('team1','team2') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lapangan` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `venue` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_date` date NOT NULL,
  `kickoff` time DEFAULT NULL,
  `team1_id` bigint unsigned DEFAULT NULL,
  `team2_id` bigint unsigned DEFAULT NULL,
  `team1_score` tinyint unsigned NOT NULL DEFAULT '0',
  `team2_score` tinyint unsigned NOT NULL DEFAULT '0',
  `penalty1` tinyint unsigned DEFAULT NULL,
  `penalty2` tinyint unsigned DEFAULT NULL,
  `is_penalty` tinyint(1) NOT NULL DEFAULT '0',
  `is_walkover` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('scheduled','live','finished') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `period` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clock` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clock_seconds` int unsigned NOT NULL DEFAULT '0',
  `clock_running` tinyint(1) NOT NULL DEFAULT '0',
  `clock_updated_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `matches_team1_id_foreign` (`team1_id`),
  KEY `matches_team2_id_foreign` (`team2_id`),
  KEY `matches_match_date_status_index` (`match_date`,`status`),
  KEY `matches_category_index` (`category`),
  KEY `matches_winner_next_match_id_foreign` (`winner_next_match_id`),
  KEY `matches_loser_next_match_id_foreign` (`loser_next_match_id`),
  CONSTRAINT `matches_loser_next_match_id_foreign` FOREIGN KEY (`loser_next_match_id`) REFERENCES `matches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `matches_team1_id_foreign` FOREIGN KEY (`team1_id`) REFERENCES `teams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `matches_team2_id_foreign` FOREIGN KEY (`team2_id`) REFERENCES `teams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `matches_winner_next_match_id_foreign` FOREIGN KEY (`winner_next_match_id`) REFERENCES `matches` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

